begin;
do $test$ declare company uuid; auth_id uuid:='73000000-0000-4000-8000-000000000001'; app_id uuid; lead_id uuid:='73000000-0000-4000-8000-000000000002'; estimate_id uuid:='73000000-0000-4000-8000-000000000003'; attempt_id uuid:='73000000-0000-4000-8000-000000000004'; asset_id uuid:='73000000-0000-4000-8000-000000000005'; outcome record; item_ids uuid[]; visit uuid; case_id uuid; rev integer;
begin select id into strict company from public.company_settings;insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values(auth_id,'authenticated','authenticated','visit@example.invalid','{}','{}',now(),now());insert into public.app_users(auth_user_id,company_id,display_name,email,role,default_portal,preferred_language,is_active,permissions,metadata)values(auth_id,company,'Visit','visit@example.invalid','estimator','sales','en',true,'{"capture_site_visits":true}'::jsonb,'{}') returning id into app_id;insert into public.leads(id,name,phone,description,status)values(lead_id,'Visit lead','555-0100','Deck','new');insert into public.estimates(id,lead_id,title,status,calculation_policy_version,calculation_revision,overhead_percent,profit_markup_percent,tax_rate_percent,discount_type,discount_value,costs_complete,prices_complete)values(estimate_id,lead_id,'Visit estimate','draft','structured-estimate-v2-material-tax',0,0,0,0,'fixed_amount',0,true,true);
select * into outcome from public.start_guided_deck_site_visit(auth_id,estimate_id,true);if outcome.result_code<>'ok' then raise exception 'start failed';end if;visit:=outcome.visit_id;rev:=outcome.revision;select v.case_id,array_agg(i.id order by i.ordinal) into case_id,item_ids from public.guided_site_visits v join public.guided_site_visit_items i on i.visit_id=v.id where v.id=visit group by v.case_id;if cardinality(item_ids)<>9 then raise exception 'not nine items';end if;
if not public.is_valid_guided_site_visit_observation('{"mode":"required_measurements","fields":["length"]}'::jsonb,'{"measurements":{"length":{"value":"12","unit":"ft"}}}'::jsonb) then raise exception 'valid measurement rejected';end if;
if public.is_valid_guided_site_visit_observation('{"mode":"required_measurements","fields":["length"]}'::jsonb,'{"measurements":{"length":{"value":"","unit":"ft"}}}'::jsonb) then raise exception 'blank measurement accepted';end if;
if public.is_valid_guided_site_visit_observation('{"mode":"required_measurements","fields":["length"]}'::jsonb,'{"measurements":{"length":{"value":"12","unit":"ft"},"extra":{"value":"1","unit":"ft"}}}'::jsonb) then raise exception 'extra measurement accepted';end if;
if not public.is_valid_guided_site_visit_observation('{"mode":"conditional","fields":["ledger_length"],"otherwise":"confirm_detached"}'::jsonb,'{"conditionStatus":"not_applicable","confirmation":"confirm_detached"}'::jsonb) then raise exception 'conditional confirmation rejected';end if;
if public.is_valid_guided_site_visit_observation('{"mode":"conditional","fields":["ledger_length"],"otherwise":"confirm_detached"}'::jsonb,'{"conditionStatus":"not_applicable","confirmation":"wrong"}'::jsonb) then raise exception 'wrong conditional confirmation accepted';end if;
if not public.is_valid_guided_site_visit_observation('{"mode":"conditional","fields":["post_dimensions","support_spacing","exposed_footing_dimensions"]}'::jsonb,'{"conditionStatus":"applies","measurements":{"post_dimensions":{"value":"4 × 4","unit":"in"},"support_spacing":{"value":"6","unit":"ft"},"exposed_footing_dimensions":{"value":"12 × 12 × 8","unit":"in"}}}'::jsonb) then raise exception 'legacy dimension keys rejected component-formatted human values';end if;
if public.is_valid_guided_site_visit_observation('{"mode":"conditional","fields":["post_dimensions","support_spacing","exposed_footing_dimensions"]}'::jsonb,'{"conditionStatus":"applies","measurements":{"post_width":{"value":"4","unit":"in"},"post_depth":{"value":"4","unit":"in"},"support_spacing":{"value":"6","unit":"ft"},"exposed_footing_width":{"value":"12","unit":"in"},"exposed_footing_length":{"value":"12","unit":"in"},"exposed_height_or_depth":{"value":"8","unit":"in"}}}'::jsonb) then raise exception 'unversioned component keys bypassed template snapshot';end if;
select * into outcome from public.reserve_guided_site_visit_photo(auth_id,visit,item_ids[1],rev,attempt_id,asset_id,company::text||'/'||case_id::text||'/'||asset_id::text||'/photo.jpg','photo.jpg','image/jpeg',128,repeat('a',64),null);if outcome.result_code<>'ok' then raise exception 'photo reservation failed: %',outcome.result_code;end if;rev:=outcome.next_revision;
select * into outcome from public.reserve_guided_site_visit_photo(auth_id,visit,item_ids[1],rev,'73000000-0000-4000-8000-000000000006','73000000-0000-4000-8000-000000000007',company::text||'/'||case_id::text||'/73000000-0000-4000-8000-000000000007/photo.jpg','photo.jpg','image/jpeg',128,repeat('b',64),null);if outcome.result_code<>'current_photo_exists' then raise exception 'parallel photo reservation accepted';end if;
select * into outcome from public.fail_guided_site_visit_photo_reservation(auth_id,visit,attempt_id,rev);if outcome.result_code<>'ok' then raise exception 'photo reservation recovery failed';end if;rev:=outcome.next_revision;if (select state from public.guided_site_visit_photo_attempts where id=attempt_id)<>'failed_validation' then raise exception 'failed reservation remained current';end if;
select * into outcome from public.reserve_guided_site_visit_photo(auth_id,visit,item_ids[1],rev,'73000000-0000-4000-8000-000000000008','73000000-0000-4000-8000-000000000009',company::text||'/'||case_id::text||'/73000000-0000-4000-8000-000000000009/retry.jpg','retry.jpg','image/jpeg',128,repeat('c',64),null);if outcome.result_code<>'ok' then raise exception 'retry after abandoned reservation failed: %',outcome.result_code;end if;rev:=outcome.next_revision;
select * into outcome from public.fail_guided_site_visit_photo_reservation(auth_id,visit,'73000000-0000-4000-8000-000000000008',rev);if outcome.result_code<>'ok' then raise exception 'retry cleanup failed';end if;rev:=outcome.next_revision;
for i in 1..8 loop select * into outcome from public.update_guided_site_visit_item(auth_id,visit,item_ids[i],rev,'document_follow_up','{}','office_verification_required','Documented for office follow-up');if outcome.result_code<>'ok' then raise exception 'follow-up failed';end if;rev:=outcome.next_revision;end loop;
select * into outcome from public.complete_guided_site_visit(auth_id,visit,rev);if outcome.result_code<>'incomplete' then raise exception 'pending item completed';end if;
select * into outcome from public.update_guided_site_visit_item(auth_id,visit,item_ids[9],rev,'document_follow_up','{}','inaccessible','Documented inaccessible condition');rev:=outcome.next_revision;select * into outcome from public.complete_guided_site_visit(auth_id,visit,rev);if outcome.result_code<>'ok' or outcome.completion_outcome<>'documented_with_office_follow_up' then raise exception 'follow-up outcome failed';end if;if (select calculation_revision from public.estimates where id=estimate_id)<>0 then raise exception 'estimate mutated';end if;
end $test$;rollback;
